def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    colors = [v for v in set(v for row in grid for v in row) if v != bg]
    if not colors:
        return [row[:] for row in grid]
    color = colors[0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            if ((0 < c < w-1 and grid[r][c-1] == color and grid[r][c+1] == color) or
                (0 < r < h-1 and grid[r-1][c] == color and grid[r+1][c] == color)):
                out[r][c] = 2
    return out
